package public_test

import (
	"crypto/x509"
	"encoding/base64"
	"encoding/pem"
	"testing"

	"github.com/mdobak/go-xerrors"
	"github.com/thisisibrahimd/telesto/internal/utils"
)

func TestParseCertificate(t *testing.T) {
	tests := []struct {
		name string // description of this test case
		// Named input parameters for target function.
		bundle []byte
	}{
		{
			name:   "single cert bundle parse",
			bundle: utils.Must(base64.RawStdEncoding.DecodeString("")),
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			block, _ := pem.Decode(tt.bundle)
			_, err := x509.ParseCertificate(block.Bytes)
			if err != nil {
				t.Error(xerrors.New("error parsing bundle", err))
			}
		})
	}
}
